import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useCart } from '../context/CartContext';
import { useAuth } from '../context/AuthContext';
import { orderAPI } from '../services/api';
import toast from 'react-hot-toast';

const DELIVERY_SLOTS = [
  '8:00 AM – 10:00 AM',
  '10:00 AM – 12:00 PM',
  '12:00 PM – 2:00 PM',
  '2:00 PM – 4:00 PM',
  '4:00 PM – 6:00 PM',
  '6:00 PM – 8:00 PM',
];

/** * FIX 1: Component defined OUTSIDE to prevent focus loss 
 */
const FormField = ({ label, name, value, onChange, errors, type = 'text', placeholder, required, half, readOnly }) => (
  <div style={{ flex: half ? '1' : undefined, minWidth: half ? 130 : undefined }}>
    <label style={{ display: 'block', fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 15, color: 'var(--gray-700)', marginBottom: 7 }}>
      {label}{required && <span style={{ color: '#dc2626' }}> *</span>}
    </label>
    <input
      name={name} // Vital for handleInputChange
      type={type}
      value={value}
      onChange={onChange}
      placeholder={placeholder}
      readOnly={readOnly}
      style={{ 
        width: '100%',
        padding: '12px',
        fontSize: 16, 
        borderRadius: '10px',
        border: `1px solid ${errors[name] ? '#dc2626' : '#d1d5db'}`, 
        background: readOnly ? 'var(--gray-50)' : 'white',
        outline: 'none',
        transition: 'border-color 0.2s'
      }}
    />
    {errors[name] && <div style={{ color: '#dc2626', fontSize: 12, marginTop: 4 }}>⚠️ {errors[name]}</div>}
  </div>
);

const CheckoutPage = () => {
  const { cart, cartTotal, clearCart } = useCart();
  const { user } = useAuth();
  const navigate = useNavigate();

  const [form, setForm] = useState({
    name: '',
    phone: '',
    email: '',
    street: '',
    city: '',
    state: '',
    pincode: '',
    slot: DELIVERY_SLOTS[0],
    notes: '',
  });

  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});

  /**
   * FIX 2: Dynamic redirection logic
   */
  useEffect(() => {
    if (!user) {
      navigate('/login', { state: { from: '/checkout' } });
    } else if (cart.length === 0) {
      navigate('/cart');
    }
  }, [user, cart.length, navigate]);

  /**
   * FIX 3: Sync user data when it arrives from AuthContext
   */
  useEffect(() => {
    if (user) {
      setForm(prev => ({
        ...prev,
        name: user.name || '',
        phone: user.phone || '',
        email: user.email || '',
        street: user.address?.street || '',
        city: user.address?.city || '',
        state: user.address?.state || '',
        pincode: user.address?.pincode || '',
      }));
    }
  }, [user]);

  const deliveryFee = cartTotal >= 499 ? 0 : 40;
  const grandTotal = cartTotal + deliveryFee;

  // Generic input handler
  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
    // Clear error for this field
    if (errors[name]) setErrors(prev => ({ ...prev, [name]: null }));
  };

  const validate = () => {
    const e = {};
    if (!form.name.trim()) e.name = 'Name required';
    if (!form.phone || form.phone.replace(/\D/g, '').length < 10) e.phone = 'Valid mobile number required';
    if (!form.street.trim()) e.street = 'Address required';
    if (!form.city.trim()) e.city = 'City required';
    if (!form.state.trim()) e.state = 'State required';
    if (!form.pincode || form.pincode.replace(/\D/g, '').length < 6) e.pincode = 'Valid pincode required';
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) {
      toast.error('Please fill all required fields');
      return;
    }
    setLoading(true);
    try {
      const res = await orderAPI.place({
        customerName: form.name,
        customerPhone: form.phone.replace(/\D/g, '').slice(-10),
        customerEmail: form.email,
        address: { 
          street: form.street, 
          city: form.city, 
          state: form.state, 
          pincode: form.pincode 
        },
        items: cart.map(i => ({ productId: i._id, quantity: i.qty })),
        deliverySlot: form.slot,
        notes: form.notes,
        totalAmount: grandTotal, // Ensure backend gets the final total
      });
      
      clearCart();
      navigate('/order-success', { state: { order: res.data.order } });
    } catch (err) {
      toast.error(err.response?.data?.message || 'Order failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  if (!user || cart.length === 0) return null;

  return (
    <div className="page-fade">
      <div className="page-header">
        <div className="container"><h1>📦 Checkout</h1></div>
      </div>
      
      <div className="container" style={{ paddingBottom: 50 }}>
        <form onSubmit={handleSubmit}>
          <div style={{ display: 'flex', gap: 24, alignItems: 'flex-start', flexWrap: 'wrap' }}>
            
            {/* Left Side: Delivery Details */}
            <div style={{ flex: 1, minWidth: 300, display: 'flex', flexDirection: 'column', gap: 20 }}>
              
              <div style={{ background: 'white', borderRadius: 18, padding: 24, boxShadow: '0 2px 10px rgba(0,0,0,0.05)' }}>
                <h3 style={{ fontSize: 20, marginBottom: 20, color: 'var(--gray-800)' }}>👤 Contact Information</h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                  <FormField label="Full Name" name="name" value={form.name} onChange={handleChange} errors={errors} required />
                  <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
                    <FormField label="Mobile" name="phone" type="tel" value={form.phone} onChange={handleChange} errors={errors} required half readOnly={!!user.phone} />
                    <FormField label="Email" name="email" type="email" value={form.email} onChange={handleChange} errors={errors} half />
                  </div>
                </div>
              </div>

              <div style={{ background: 'white', borderRadius: 18, padding: 24, boxShadow: '0 2px 10px rgba(0,0,0,0.05)' }}>
                <h3 style={{ fontSize: 20, marginBottom: 20, color: 'var(--gray-800)' }}>📍 Delivery Address</h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                  <FormField label="House / Street / Area" name="street" value={form.street} onChange={handleChange} errors={errors} required />
                  <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
                    <FormField label="City" name="city" value={form.city} onChange={handleChange} errors={errors} required half />
                    <FormField label="State" name="state" value={form.state} onChange={handleChange} errors={errors} required half />
                  </div>
                  <FormField label="Pincode" name="pincode" value={form.pincode} onChange={handleChange} errors={errors} required />
                </div>
              </div>

              <div style={{ background: 'white', borderRadius: 18, padding: 24, boxShadow: '0 2px 10px rgba(0,0,0,0.05)' }}>
                <h3 style={{ fontSize: 20, marginBottom: 12 }}>🕐 Delivery Slot</h3>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))', gap: 10 }}>
                  {DELIVERY_SLOTS.map(s => (
                    <button key={s} type="button" onClick={() => setForm(f => ({ ...f, slot: s }))}
                      style={{ 
                        padding: '12px 6px', borderRadius: 10, cursor: 'pointer', fontSize: 13, fontWeight: 600,
                        border: `2px solid ${form.slot === s ? 'var(--green)' : '#eee'}`,
                        background: form.slot === s ? 'var(--green-bg)' : 'white',
                        color: form.slot === s ? 'var(--green-dark)' : '#666'
                      }}>
                      {s}
                    </button>
                  ))}
                </div>
              </div>

              <div style={{ background: 'white', borderRadius: 18, padding: 24, boxShadow: '0 2px 10px rgba(0,0,0,0.05)' }}>
                <label style={{ fontWeight: 700, display: 'block', marginBottom: 10 }}>📝 Delivery Instructions</label>
                <textarea name="notes" value={form.notes} onChange={handleChange} placeholder="Any specific directions?" rows={3} style={{ width: '100%', borderRadius: 10, padding: 12, border: '1px solid #d1d5db', outline: 'none' }} />
              </div>
            </div>

            {/* Right Side: Order Summary */}
            <div style={{ width: 340, background: 'white', borderRadius: 20, padding: 24, boxShadow: '0 10px 30px rgba(0,0,0,0.08)', position: 'sticky', top: 90 }}>
              <h3 style={{ fontSize: 22, marginBottom: 20 }}>🧾 Order Summary</h3>
              <div style={{ maxHeight: 250, overflowY: 'auto', marginBottom: 15 }}>
                {cart.map(item => (
                  <div key={item._id} style={{ display: 'flex', gap: 12, marginBottom: 12, alignItems: 'center' }}>
                    <img src={item.image} alt="" style={{ width: 45, height: 45, borderRadius: 8, objectFit: 'cover' }} />
                    <div style={{ flex: 1 }}>
                      <div style={{ fontWeight: 600, fontSize: 14 }}>{item.name}</div>
                      <div style={{ color: '#888', fontSize: 12 }}>Qty: {item.qty}</div>
                    </div>
                    <div style={{ fontWeight: 700 }}>₹{item.price * item.qty}</div>
                  </div>
                ))}
              </div>

              <div style={{ borderTop: '2px dashed #eee', paddingTop: 15 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 10 }}>
                  <span>Subtotal</span><span>₹{cartTotal}</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 15 }}>
                  <span>Delivery Fee</span>
                  <span style={{ color: 'var(--green)', fontWeight: 700 }}>{deliveryFee === 0 ? 'FREE' : `₹${deliveryFee}`}</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', borderTop: '1px solid #eee', paddingTop: 15, marginBottom: 25 }}>
                  <span style={{ fontSize: 18, fontWeight: 800 }}>Total</span>
                  <span style={{ fontSize: 24, fontWeight: 800, color: 'var(--green)' }}>₹{grandTotal}</span>
                </div>
              </div>

              <div style={{ background: '#fff7ed', border: '1px solid #fdba74', borderRadius: 12, padding: 12, marginBottom: 20, textAlign: 'center' }}>
                <div style={{ fontWeight: 800, color: '#c2410c' }}>Cash on Delivery</div>
              </div>

              <button type="submit" disabled={loading} style={{ 
                width: '100%', padding: '16px', borderRadius: 12, border: 'none', color: 'white', fontSize: 18, fontWeight: 800,
                background: loading ? '#ccc' : 'linear-gradient(to right, var(--green), var(--green-dark))',
                cursor: loading ? 'not-allowed' : 'pointer'
              }}>
                {loading ? 'Processing...' : 'Place Order'}
              </button>
            </div>

          </div>
        </form>
      </div>
    </div>
  );
};

export default CheckoutPage;